<script>
const billingButtons = document.querySelectorAll('"'[data-billing]');
const currency = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
billingButtons.forEach(button => {
  button.addEventListener('click', () => {
    const yearly = button.dataset.billing === 'yearly';
    billingButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
    document.querySelectorAll('[data-price]').forEach(item => {
      const monthlyPrice = Number(item.dataset.price);
      item.textContent = yearly ? (monthlyPrice * .8).toFixed(2) : monthlyPrice;
    });
    document.querySelector('[data-note=\"pro\"]').textContent = yearly ? currency.format(8 * .8 * 12) + ' billed yearly' : 'Billed monthly';
    document.querySelector('[data-note=\"team\"]').textContent = yearly ? currency.format(14 * .8 * 12) + ' per user, billed yearly' : 'Billed monthly';
    document.querySelector('#billing-status').textContent = yearly ? 'Yearly billing selected. Monthly rates include a 20% discount. Pro is "'$76.80 per year; Team is $134.40 per user per year.'"' : 'Monthly billing selected. Pro is "'$8 per month; Team is $14 per user per month.'"';
  });
});
</script>
</body>
